import * as fs from 'fs';

interface CLIArgs {
  group: string;
}

function parseArgs(argv: string[]): CLIArgs {
  const args: CLIArgs = { group: '' };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--group') {
      const v = argv[i + 1];
      if (!v) throw new Error('Missing value for --group');
      args.group = v;
      i++;
